import{_ as i,l as s,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"近存与存内计算","description":"","frontmatter":{"title":"近存与存内计算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pim-near-memory.md","filePath":"cs/pim-near-memory.md","lastUpdated":1789023840000}'),p={name:"cs/pim-near-memory.md"};function h(A,a,_,f,M,E){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="近存与存内计算" tabindex="-1">近存与存内计算 <a class="header-anchor" href="#近存与存内计算" aria-label="Permalink to &quot;近存与存内计算&quot;">​</a></h1><div class="epigraph"><p>能耗与延迟的大头往往是把数据搬到很远的 ALU；把简单运算放到 DRAM 接口甚至阵列里，搬动的字节下降，可编程性也下降。</p><footer>—— 据 Patterson et al., A Case for Intelligent RAM, IEEE Micro 1997；后续近存架构综述 整理</footer></div><p><a href="/cs/dsa-accelerator">上一课</a> 仍通常经过 DMA 把数据拉进加速器 SRAM。<a href="/cs/roofline-model">Roofline</a> 还没讲，但算术强度低时已经能感觉到带宽墙。本课不重讲作业队列。缺口是 <strong>近存（near-memory）与存内（in-memory）计算：缩短或取消搬移。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>cache 层次假设复用；扫描一次的负载复用差，<a href="/cs/stride-stream-prefetch">预取</a> 只是提前搬，字节仍过片上互连。缺口不是再加一层 LLC，而是<strong>在 HBM/DRAM 栈上放简易 ALU，或在阵列里做按位/按行运算。</strong> IRAM 把处理器与 DRAM 做在一起；当代 PIM 常是逻辑工艺与 DRAM 工艺的叠层妥协。</p><p><span class="marginnote">Patterson 的 IRAM：向量/处理器靠近 DRAM，利用内带宽。真「存内」在存储单元上做模拟或数字运算，噪声与 ISA 都难，近存更常见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>近存：在内存控制器或 base die 上放 SIMD/规约单元，CPU 下发「对这片地址做规约」。存内：在 bank 内广播行、做按位与或，再读出。一致性：这些运算如何与 <a href="/cs/mesi-protocol">MESI</a> 共存是未决设计，常绕过 cache 或先冲刷。</p>',8)),(e(),n(m,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%22%5D%20--%3E%20CMD%5B%22%E8%BF%91%E5%AD%98%E5%91%BD%E4%BB%A4%22%5D%0A%20%20CMD%20--%3E%20NM%5B%22DRAM%20%E6%97%81%20ALU%22%5D%0A%20%20NM%20--%3E%20DRAM%5B%22%E6%9C%AC%E5%9C%B0%E5%B8%A6%E5%AE%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>省的是互连与 cache 填入，不是算法复杂度。不规则 gather 仍痛。与 GPU HBM：GPU 已经较近，PIM 更近一步、更笨。不要写成量化交易的内存；不要写成大模型权重驻留方案的产品页。</p><p>编程模型通常是「对这段连续物理内存做 map/reduce」，而不是任意 load/store ISA。OS 要把页钉住并冲刷 cache，否则近存 ALU 看见的是陈旧行。这与 <a href="/cs/write-combining">写合并</a> 的 drain 同一类正确性点，只是发生在内存控制器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不承诺某工艺可量产的存内精度。异构 SoC 下一课把 CPU 大核、小核、GPU、DSA、内存侧设备放在同一芯片上的调度问题提出来。</p><p>后课默认：搬移主导时考虑近存。同一硅上多种流水线的编排是 big.LITTLE 与异构 SoC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>近存减少搬移；真存内更激进、更难与 ISA/一致性共存。</li><li>低复用扫描最受益。</li><li>大小核与加速器共存是下一课异构 SoC。</li><li>出处：Patterson et al., <em>IEEE Micro</em>, 1997。</li></ul>',8))])}const D=i(p,[["render",h]]);export{u as __pageData,D as default};
